<style>
*{box-sizing:border-box}body{margin:0;background:#f2f5fa;color:#183153;font-family:Arial,sans-serif}.page{flex:1;min-width:0;padding:24px}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:20px}h1{font-size:24px;margin:0  auto 0 0}.button,button{display:inline-block;padding:10px 16px;border:1px solid #cad5e4;border-radius:8px;background:white;color:#183153;font:inherit;text-decoration:none;cursor:pointer}.primary{background:#214b85;color:white;border-color:#214b85}.danger{color:#b42318}.status{background:#e7f4eb;padding:12px;border-radius:8px;margin:12px 0}.errors{background:#fff0ed;color:#9a2319;padding:14px;margin:12px 0}.hint{color:#65758a;font-size:13px}.paper{max-width:1000px;margin:auto;background:white;padding:42px;box-shadow:0 3px 20px #18315312;color:#111;font-family:'Times New Roman',serif}.paper h2{text-align:center;font-size:24px;margin:0 0 16px}.paper h3{text-align:center;font-size:21px;margin:0 0 18px}.invoice-date{text-align:center;margin-bottom:20px;font-size:18px;font-weight:bold}.invoice-date input{width:155px!important}.paper table{width:100%;border-collapse:collapse;table-layout:fixed}.paper td,.paper th{border:1px solid #333;padding:5px;vertical-align:top}.customer{margin:0 auto 32px;width:78%!important}.paper input,.paper textarea{width:100%;min-width:0;border:1px solid transparent;background:transparent;color:#111;font:inherit;padding:4px;border-radius:2px}.paper input:hover,.paper textarea:hover{background:#f4f7fd}.paper input:focus,.paper textarea:focus{outline:2px solid #6d96d4;background:#f4f7fd}.paper textarea{resize:vertical;overflow:hidden;min-height:30px}.paper input[type=number]{appearance:textfield}.paper input::-webkit-inner-spin-button{appearance:none}.items th{font-weight:bold;text-align:center}.items td.number,.money{text-align:right;white-space:nowrap}.items input[type=number]{text-align:right}.items td:first-child{text-align:center}.row-actions{margin:16px 0}.total td{font-weight:bold}.total td:first-child{text-align:center}.delete-row{padding:2px 6px;color:#a32121;border:0;background:none}.print-value{display:none;white-space:pre-wrap;overflow-wrap:anywhere}.list-table{width:100%;border-collapse:collapse;background:white}.list-table td,.list-table th{text-align:left;padding:14px;border-bottom:1px solid #dce4ef}.list-table form{display:inline}.list-table a{color:#214b85}.list-wrap{overflow:auto}.search{display:flex;gap:10px;margin:16px 0}.search input{padding:10px;border:1px solid #cad5e4;border-radius:8px;min-width:260px}
